# Golden-data regression helpers. The reference CSVs were generated by v0.2 (MTK 8.71)
# and must not be regenerated: they pin the physics. Each case maps a golden column
# to a variable of the v0.3 model; `flip` marks columns whose bond is drawn the other
# way in v0.3, so the variable has the opposite sign.
using DelimitedFiles

const REF_DIR = joinpath(@__DIR__, "reference")
const TS = range(0.0, 10.0, length = 21)  # sample times shared by every case

function check_case(case, model, cols; u0 = [], flip = String[])
    sol = solve(ODEProblem(mtkcompile(model), u0, (0.0, 10.0)), Tsit5(); abstol = 1e-10, reltol = 1e-10)
    @test SciMLBase.successful_retcode(sol)
    ref, header = readdlm(joinpath(REF_DIR, "$case.csv"), ',', Float64; header = true)
    header = vec(header)
    @test ref[:, 1] ≈ TS
    @test Set(first.(cols)) == Set(header[2:end])  # every golden column is checked
    for (name, var) in cols
        expected = (name in flip ? -1 : 1) .* ref[:, findfirst(==(name), header)]
        @test all(isapprox.(sol(TS; idxs = var), expected; rtol = 1e-6, atol = 1e-9))
    end
end
